/**
 * Central SEO primitives — single source of truth for canonical URLs,
 * structured data, and the route registry used by the sitemap.
 */

export const SITE = {
  url: "https://solyio.com",
  name: "Solyio",
  tagline: "Web, Mobile, Cloud & AI Solutions",
  description:
    "Solyio builds web platforms, mobile apps, cloud infrastructure, and AI automation that simplify your business and accelerate growth.",
  email: "hello@solyio.com",
  phone: "+1-678-551-7478",
  twitter: "@solyio",
  foundingDate: "2024",
  logo: "/logo.svg",
  /** Social cards are generated by app/opengraph-image.tsx, not a static file. */
  ogImage: "/opengraph-image",
} as const

export function absoluteUrl(path = "/"): string {
  if (path.startsWith("http")) return path
  return `${SITE.url}${path.startsWith("/") ? path : `/${path}`}`
}

/**
 * Next merges `metadata.openGraph` SHALLOWLY — a page that declares the object
 * at all replaces the root layout's entirely, silently dropping og:image.
 * Spread this into every page-level openGraph block so the card never breaks.
 *
 * Images are generated at build time by the `opengraph-image` file convention,
 * so there is no static asset to go missing.
 */
export function ogImage(path = "/opengraph-image", alt = `${SITE.name} — ${SITE.tagline}`) {
  return [{ url: path, width: 1200, height: 630, alt, type: "image/png" }]
}

/* ─── Route registry ─────────────────────────────────────────────── */

type ChangeFreq = "always" | "hourly" | "daily" | "weekly" | "monthly" | "yearly" | "never"

export interface RouteEntry {
  path: string
  changeFrequency: ChangeFreq
  priority: number
}

