/* ─── Structured data ────────────────────────────────────────────── */

export const ORGANIZATION_ID = `${SITE.url}/#organization`
export const WEBSITE_ID = `${SITE.url}/#website`

export const organizationSchema = {
  "@context": "https://schema.org",
  "@type": "Organization",
  "@id": ORGANIZATION_ID,
  name: SITE.name,
  url: SITE.url,
  logo: {
    "@type": "ImageObject",
    url: absoluteUrl(SITE.logo),
  },
  description: SITE.description,
  foundingDate: SITE.foundingDate,
  slogan: SITE.tagline,
  knowsAbout: [
    "Web Development",
    "Mobile App Development",
    "Cloud Infrastructure",
    "AI Automation",
    "AI Agents",
    "Cyber Security",
    "SaaS Product Engineering",
  ],
  sameAs: [
    "https://twitter.com/solyio",
    "https://linkedin.com/company/solyio",
    "https://github.com/solyio",
  ],
  contactPoint: [
    {
      "@type": "ContactPoint",
      telephone: SITE.phone,
      contactType: "sales",
      email: SITE.email,
      availableLanguage: ["English"],
      areaServed: ["US", "GB", "DE", "FR", "NL", "ES", "IT", "CA", "AU"],
    },
  ],
  areaServed: [
    { "@type": "Country", name: "United States" },
    { "@type": "Country", name: "United Kingdom" },
    { "@type": "Country", name: "Germany" },
    { "@type": "Country", name: "France" },
    { "@type": "Country", name: "Netherlands" },
  ],
}

export const websiteSchema = {
  "@context": "https://schema.org",
  "@type": "WebSite",
  "@id": WEBSITE_ID,
  url: SITE.url,
  name: SITE.name,
  description: SITE.description,
  inLanguage: "en",
  publisher: { "@id": ORGANIZATION_ID },
}

export interface Crumb {
  name: string
  path: string
}

/** BreadcrumbList for a specific page. Always lead with Home. */
export function breadcrumbSchema(crumbs: Crumb[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [{ name: "Home", path: "/" }, ...crumbs].map((c, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: c.name,
      item: absoluteUrl(c.path),
    })),
  }
}

export interface Faq {
  q: string
  a: string
}

/** FAQPage — only ever emit this on a page whose visible content shows these Q&As. */
export function faqSchema(faqs: Faq[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  }
}

export function serviceSchema(opts: {
  name: string
  serviceType: string
  description: string
  path: string
  offers?: { name: string; description: string }[]
}) {
  return {
    "@context": "https://schema.org",
    "@type": "Service",
    "@id": `${absoluteUrl(opts.path)}#service`,
    name: opts.name,
    serviceType: opts.serviceType,
    description: opts.description,
    url: absoluteUrl(opts.path),
    provider: { "@id": ORGANIZATION_ID },
    areaServed: "Worldwide",
    ...(opts.offers?.length
      ? {
          hasOfferCatalog: {
            "@type": "OfferCatalog",
            name: `${opts.name} Packages`,
            itemListElement: opts.offers.map((o) => ({
              "@type": "Offer",
              itemOffered: { "@type": "Service", name: o.name, description: o.description },
            })),
          },
        }
      : {}),
  }
}
